package com.google.gson.stream;

import com.google.gson.Gson;
import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class JsonWriter_value_TriageGen1Test {

    @Test
    public void testValue_NullValue() throws IOException {
        JsonWriter jsonWriter = new JsonWriter(new StringWriter());
        jsonWriter.setLenient(true);
        jsonWriter.value(null);
        assertNull(jsonWriter.toString());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testValue_InfinityValue() throws IOException {
        JsonWriter jsonWriter = new JsonWriter(new StringWriter());
        jsonWriter.setLenient(false);
        jsonWriter.value(Double.POSITIVE_INFINITY);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testValue_NegativeInfinityValue() throws IOException {
        JsonWriter jsonWriter = new JsonWriter(new StringWriter());
        jsonWriter.setLenient(false);
        jsonWriter.value(Double.NEGATIVE_INFINITY);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testValue_NaNValue() throws IOException {
        JsonWriter jsonWriter = new JsonWriter(new StringWriter());
        jsonWriter.setLenient(false);
        jsonWriter.value(Double.NaN);
    }

    @Test
    public void testValue_FiniteValue() throws IOException {
        JsonWriter jsonWriter = new JsonWriter(new StringWriter());
        jsonWriter.setLenient(true);
        jsonWriter.value(123);
        assertEquals("\"123\"", jsonWriter.toString());
    }

    @Test
    public void testValue_BigIntegerValue() throws IOException {
        JsonWriter jsonWriter = new JsonWriter(new StringWriter());
        jsonWriter.setLenient(true);
        jsonWriter.value(BigInteger.valueOf(123));
        assertEquals("\"123\"", jsonWriter.toString());
    }

    @Test
    public void testValue_BigDecimalValue() throws IOException {
        JsonWriter jsonWriter = new JsonWriter(new StringWriter());
        jsonWriter.setLenient(true);
        jsonWriter.value(BigDecimal.valueOf(123));
        assertEquals("\"123\"", jsonWriter.toString());
    }

    @Test
    public void testValue_BooleanValue() throws IOException {
        JsonWriter jsonWriter = new JsonWriter(new StringWriter());
        jsonWriter.setLenient(true);
        jsonWriter.value(true);
        assertEquals("\"true\"", jsonWriter.toString());
    }

    @Test
    public void testValue_StringValue() throws IOException {
        JsonWriter jsonWriter = new JsonWriter(new StringWriter());
        jsonWriter.setLenient(true);
        jsonWriter.value("hello");
        assertEquals("\"hello\"", jsonWriter.toString());
    }
}
